from textutil.truncate import truncate


def test_short_text_untouched():
    assert truncate("short", 10) == "short"


def test_word_boundary():
    assert truncate("The quick brown fox jumps", 15) == "The quick..."


def test_within_limit():
    assert len(truncate("alpha beta gamma delta", 12)) <= 12


def test_hard_cut_legacy():
    # mobile previews need exactly `limit` characters (opt-in)
    assert truncate("The quick brown fox jumps", 15, hard_cut=True) == "The quick br..."


def test_single_long_word_hard_cut():
    assert truncate("Supercalifragilistic", 10) == "Superca..."


def test_result_within_limit_default():
    for limit in range(4, 30):
        out = truncate("The quick brown fox jumps over the lazy dog", limit)
        assert len(out) <= limit
        assert out.endswith("...")
